const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Define geometries - Mesquite Flat (valley floor) and Panamint Mountains
  const mesquiteFlatGeom = ee.Geometry.Point([-117.0, 36.72]);
  const panamintGeom = ee.Geometry.Point([-117.1, 36.4]);

  // 2. Data acquisition
  const startDate = '2013-06-30';
  const endDate = '2013-07-01';

  let collection = ee.ImageCollection('LANDSAT/LC08/C02/T1_L2')
    .filterDate(startDate, endDate)
    .filterBounds(mesquiteFlatGeom.buffer(10000));

  const colSize = await collection.size().getInfo();
  console.log(`Images found: ${colSize}`);

  if (colSize === 0) {
    console.log('No Landsat 8 images found for June 30, 2013');
    console.log('<answer>C1</answer>');
    return;
  }

  // 3. Cloud masking function
  function maskClouds(image) {
    const qaMask = image.select('QA_PIXEL').bitwiseAnd(parseInt('11111', 2)).eq(0);
    return image.updateMask(qaMask);
  }

  // 4. Get the image and apply scaling
  let image = collection.first();
  image = maskClouds(image);

  const tempBand = image.select('ST_B10').multiply(0.00341802).add(149.0).subtract(273.15);

  // 5. Calculate temperature for Mesquite Flat
  const mesquiteStats = await tempBand.reduceRegion({
    reducer: ee.Reducer.mean().combine({
      reducer2: ee.Reducer.count(),
      sharedInputs: true
    }),
    geometry: mesquiteFlatGeom.buffer(1000),
    scale: 3000,
    maxPixels: 1e9
  }).getInfo();

  const mesquiteTemp = mesquiteStats.ST_B10_mean;
  const mesquiteCount = mesquiteStats.ST_B10_count;

  console.log(`Mesquite Flat - Temp: ${mesquiteTemp?.toFixed(2)}°C, Pixels: ${mesquiteCount}`);

  // 6. Calculate temperature for Panamint Mountains
  const panamintStats = await tempBand.reduceRegion({
    reducer: ee.Reducer.mean().combine({
      reducer2: ee.Reducer.count(),
      sharedInputs: true
    }),
    geometry: panamintGeom.buffer(1000),
    scale: 3000,
    maxPixels: 1e9
  }).getInfo();

  const panamintTemp = panamintStats.ST_B10_mean;
  const panamintCount = panamintStats.ST_B10_count;

  console.log(`Panamint Mountains - Temp: ${panamintTemp?.toFixed(2)}°C, Pixels: ${panamintCount}`);

  // 7. Validation and answer
  if (mesquiteCount === 0 || panamintCount === 0) {
    console.log('No valid pixels after masking');
    console.log('<answer>C2</answer>');
    return;
  }

  if (mesquiteTemp === null || mesquiteTemp === undefined || 
      panamintTemp === null || panamintTemp === undefined ||
      mesquiteTemp < -50 || mesquiteTemp > 100 ||
      panamintTemp < -50 || panamintTemp > 100) {
    console.log('Invalid temperature values');
    console.log('<answer>C3</answer>');
    return;
  }

  console.log(`Temperature difference: ${(mesquiteTemp - panamintTemp).toFixed(2)}°C`);

  if (mesquiteTemp > panamintTemp) {
    console.log('<answer>A</answer>');
  } else {
    console.log('<answer>B</answer>');
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
